update public.learning_paths
set
  title = 'Introduction to Kinesiology / Exercise Science',
  goal = 'Introduction to Kinesiology / Exercise Science',
  summary = 'Designed as a 15-module first-year gateway course. Each module can map to one week in a semester format, with short labs, observation assignments, article discussions, career explorations, and a final integrative analysis of a real movement, health, or performance problem.',
  data = $ikesjson${"slug": "introduction-to-kinesiology-exercise-science", "title": "Introduction to Kinesiology / Exercise Science", "description": "Designed as a 15-module first-year gateway course. Each module can map to one week in a semester format, with short labs, observation assignments, article discussions, career explorations, and a final integrative analysis of a real movement, health, or performance problem.", "topics": [{"id": "3179ac1a-2c1a-4705-9f50-0cfca0c62c16", "type": "topic", "title": "Kinesiology and Exercise Science Orientation: Scope, Language, and Big Questions", "description": "Define the field, its central questions, and how its subdisciplines study physical activity and human movement.", "children": [{"id": "4061c45a-af59-4cba-8cc2-ffba4536cbb2", "type": "subtopic", "title": "Defining kinesiology", "description": "Students learn what makes kinesiology a coherent discipline rather than a loose collection of sport, fitness, and health topics.", "children": [{"id": "06172ffb-1204-4c26-ba04-ba3efa3d0884", "type": "concept", "title": "Physical activity, exercise, sport, movement, performance, and health"}, {"id": "5de054e7-6049-412c-b514-04f2efeafc2f", "type": "concept", "title": "Basic distinctions among kinesiology, exercise science, physical education, sport science, and rehabilitation sciences"}, {"id": "f9807c25-e820-4cf5-9ba1-4e2c583664d7", "type": "concept", "title": "Core questions about how humans move, adapt, learn, perform, and stay healthy"}]}, {"id": "a54df76a-6d00-468c-ba8e-766b20bf0fe1", "type": "subtopic", "title": "Subdisciplines and integration", "description": "The point is to see how each subfield contributes a different lens on the same moving human being.", "children": [{"id": "33f53d18-7666-4a15-8a3d-86d0c6e13287", "type": "concept", "title": "Biomechanics, exercise physiology, motor behavior, sport psychology, adapted physical activity, and public health"}, {"id": "590e9ccf-88f3-41d0-8a59-169a1f5fc23f", "type": "concept", "title": "Lab, field, clinical, school, community, and performance settings"}, {"id": "f37c884a-a246-4457-914d-d347d95be71a", "type": "concept", "title": "How multidisciplinary teams solve movement problems"}]}, {"id": "3a8bb546-efc8-4975-af8a-6528ff272ed1", "type": "subtopic", "title": "Learning how to think like a kinesiologist", "description": "This subtopic gives first-year students a durable way to approach the rest of the major.", "children": [{"id": "1692e934-f8ec-4883-a17c-7c7195724413", "type": "concept", "title": "Observation before explanation"}, {"id": "fc008851-7612-4a5e-aea1-c15d69239d1f", "type": "concept", "title": "Mechanism, evidence, context, and ethics"}, {"id": "77720a75-ba09-4246-943a-81986bac8b76", "type": "concept", "title": "From description to assessment to intervention"}]}]}, {"id": "35394f26-b5b5-479c-b416-e16b4c39c2e5", "type": "topic", "title": "History, Philosophy, Culture, and Ethics of Physical Activity", "description": "Understand physical activity as a biological, cultural, educational, clinical, and ethical human practice.", "children": [{"id": "ee2e46b4-90af-4129-8344-1fa58dd1ebe2", "type": "subtopic", "title": "Historical development of the field", "description": "Students place modern exercise science in a long history of physical culture, medicine, education, labor, sport, and public health.", "children": [{"id": "362ea75c-d0f4-4519-97a7-cd7eec0bba72", "type": "concept", "title": "Ancient, modern, and contemporary physical culture"}, {"id": "a52388c5-c779-4a54-b5d9-d93bdf0e7464", "type": "concept", "title": "Growth of physical education, sport science, exercise physiology, and rehabilitation"}, {"id": "d176da6f-1ef8-4c3b-b4b3-ecca117b7461", "type": "concept", "title": "Professionalization and credentialing of movement-related careers"}]}, {"id": "3f6696bc-049a-4708-a386-e822a04a2f08", "type": "subtopic", "title": "Physical activity and society", "description": "The gist is that movement is never only biological; it is shaped by culture, access, identity, and institutions.", "children": [{"id": "efd79ba1-e7b0-440b-bf1b-aee5707a07a2", "type": "concept", "title": "Sport, recreation, labor, military, school, and clinical activity traditions"}, {"id": "0fb54f29-a685-4c33-b0e2-94a66c0ac1a7", "type": "concept", "title": "Gender, race, disability, age, class, and access in physical activity"}, {"id": "8510cb5c-c5ca-470a-884d-27ebf2c582c0", "type": "concept", "title": "Media, commercialization, and body ideals"}]}, {"id": "146a5fe0-2d8a-4512-ad6c-024d33e5cd62", "type": "subtopic", "title": "Ethics in kinesiology", "description": "Learners practice spotting ethical tensions before they become professional failures.", "children": [{"id": "f221d9ab-1980-4470-90e2-6a267ab3d30e", "type": "concept", "title": "Consent, privacy, safety, and scope of practice"}, {"id": "64711263-e2ad-47e8-9a6d-6d5b67978b36", "type": "concept", "title": "Equity and inclusion in activity settings"}, {"id": "545072b0-a8b0-49eb-8527-7e742fbbb9e7", "type": "concept", "title": "Performance enhancement, technology, and conflicts of interest"}]}]}, {"id": "6391a4ab-ac9c-4c93-bd9b-b3f5001a9382", "type": "topic", "title": "Physical Activity, Public Health, Disease Prevention, and Health Equity", "description": "Connect movement to population health, chronic disease prevention, behavior, environments, and equity.", "children": [{"id": "e69e746c-4476-4ffb-a0e5-3aa767235a35", "type": "subtopic", "title": "Physical activity and health outcomes", "description": "Students learn why movement is one of the strongest modifiable determinants of health.", "children": [{"id": "6a151d08-2a37-48e6-bc95-9e11d92ecc97", "type": "concept", "title": "Cardiometabolic health, musculoskeletal health, mental health, function, and longevity"}, {"id": "fe4feecf-c089-4e59-bbce-2588fda81c09", "type": "concept", "title": "Sedentary behavior and inactivity risk"}, {"id": "ad47106d-442d-4e5c-b10a-ade0105aa2a8", "type": "concept", "title": "Dose, frequency, intensity, time, type, and progression"}]}, {"id": "dba53ee5-ada3-4c47-a208-0410cb70a4e4", "type": "subtopic", "title": "Population guidelines and behavior", "description": "This subtopic connects individual exercise advice to public-health recommendations and real-world behavior.", "children": [{"id": "7c15edc3-b7c8-4486-a0a0-6e4e3982db2e", "type": "concept", "title": "ACSM, CDC, WHO, and national physical-activity guidelines"}, {"id": "8037c3fb-580c-4328-9fc1-7d9fd7635685", "type": "concept", "title": "Barriers, facilitators, social support, built environment, and policy"}, {"id": "1be7cd83-c590-4c77-8dc8-a3941b6ee45e", "type": "concept", "title": "Health promotion across the lifespan"}]}, {"id": "8970ddd8-0cfc-4eba-a737-34dc37d4e16e", "type": "subtopic", "title": "Health equity and access", "description": "Students learn that prescribing movement without addressing context can widen disparities.", "children": [{"id": "27a527f7-67e2-43dd-acd3-58eb46916f81", "type": "concept", "title": "Social determinants of health"}, {"id": "fd3dafc1-acb8-4f21-8e73-5e0d3696237b", "type": "concept", "title": "Safe spaces, transportation, cost, time, disability access, and cultural fit"}, {"id": "9f27c807-5ae0-46bf-995e-1f6e808d76dc", "type": "concept", "title": "Community partnerships and inclusive programming"}]}]}, {"id": "c8ae6836-d18b-424e-be4b-7fadac4a9e5b", "type": "topic", "title": "Anatomy, Physiology, Homeostasis, and Human Movement Foundations", "description": "Build the basic body-systems vocabulary needed for every later kinesiology course.", "children": [{"id": "cac52c62-6e29-4439-ad5b-a1b8c2cf329f", "type": "subtopic", "title": "Body systems for movement", "description": "The goal is to give students a working vocabulary for later anatomy, physiology, and biomechanics courses.", "children": [{"id": "77647678-741b-4129-999d-12d631a67355", "type": "concept", "title": "Skeletal, muscular, nervous, cardiovascular, respiratory, endocrine, and metabolic systems"}, {"id": "0da6325f-0736-4a0f-8a9f-6e98fdd2e5fd", "type": "concept", "title": "Joints, planes, axes, and anatomical terminology"}, {"id": "33dab17b-8690-4844-9aeb-025741700267", "type": "concept", "title": "Tissues, organs, and systems-level thinking"}]}, {"id": "513a4552-e4a5-4da9-aa65-5f6665748e0f", "type": "subtopic", "title": "Homeostasis and adaptation", "description": "Students learn that exercise is a stressor that challenges and trains regulatory systems.", "children": [{"id": "26dbf95a-6a05-4bf5-81e1-3a206acf30b4", "type": "concept", "title": "Feedback loops and set points"}, {"id": "1687785d-0e31-45ec-91e1-5a5cffb6afc4", "type": "concept", "title": "Acute responses versus chronic adaptations"}, {"id": "b34eb5be-1d33-410e-956d-65458139aebc", "type": "concept", "title": "Load, recovery, fatigue, and overreaching"}]}, {"id": "ddf8f278-f3f1-4187-8d63-d37f380f6a0f", "type": "subtopic", "title": "Lab and observation basics", "description": "This subtopic introduces students to careful measurement and respect for human variability.", "children": [{"id": "0d8cc55b-c263-4404-a27e-a275bb06e2c7", "type": "concept", "title": "Vital signs and basic physiological observations"}, {"id": "546031a0-750f-43a5-9a62-007cd7e32e50", "type": "concept", "title": "Movement screens and anatomical landmarks"}, {"id": "1f4b0924-ec45-4693-8f89-9feab7b1bd0c", "type": "concept", "title": "Safety, consent, hygiene, and lab professionalism"}]}]}, {"id": "00a61cb2-83b9-4604-9d66-c9d59acc5690", "type": "topic", "title": "Biomechanics and Movement Analysis Basics", "description": "Use mechanical principles to describe, measure, and improve movement safely and effectively.", "children": [{"id": "f436eeef-3dcd-4349-a06e-eed3cda0036b", "type": "subtopic", "title": "Kinematics and movement description", "description": "Students learn to describe movement precisely before trying to improve it.", "children": [{"id": "12cd1c95-18bd-4a36-b208-aea8965efab2", "type": "concept", "title": "Linear and angular motion"}, {"id": "ae8ecd2f-14ef-4366-aa6b-91c178c90d76", "type": "concept", "title": "Planes and axes"}, {"id": "627f45f0-577b-479a-9e7b-595847c15832", "type": "concept", "title": "Position, velocity, acceleration, and range of motion"}]}, {"id": "786a893d-12d8-4899-ab4d-ba6f22cbef19", "type": "subtopic", "title": "Kinetics and force", "description": "The point is to understand how forces create, resist, and modify movement.", "children": [{"id": "c47f4370-4833-4ae6-9df9-e299ff904856", "type": "concept", "title": "Newton's laws"}, {"id": "179f6b1b-6acb-4ca5-9e4e-a83785dc4db3", "type": "concept", "title": "Ground reaction force, torque, impulse, work, energy, and power"}, {"id": "332dcef4-bbe3-4c8b-93f3-bbf27e93567b", "type": "concept", "title": "Levers, moments, and joint loading"}]}, {"id": "1f4d825a-3f35-4918-9dbe-ce10a6bf41bf", "type": "subtopic", "title": "Applied movement analysis", "description": "Learners connect mechanics to coaching, rehabilitation, ergonomics, and injury prevention.", "children": [{"id": "7211483a-4285-4f53-9666-8c38f5f4d74d", "type": "concept", "title": "Gait, jumping, lifting, throwing, and landing"}, {"id": "995c907a-6b5c-48eb-9ba5-e61f8ae9c330", "type": "concept", "title": "Video analysis and wearable sensors"}, {"id": "fe014886-412c-491d-9eef-be9566b4776b", "type": "concept", "title": "Technique, tissue loading, and performance tradeoffs"}]}]}, {"id": "b7e46ff6-551b-4f96-8220-8b947120cebb", "type": "topic", "title": "Exercise Physiology, Bioenergetics, and Acute Exercise Responses", "description": "Explain how the body produces energy and responds to exercise stress in real time.", "children": [{"id": "42b6e8ff-3fae-4adb-8b72-fa52382d2330", "type": "subtopic", "title": "Energy systems", "description": "Students learn how the body resynthesizes ATP for different exercise demands.", "children": [{"id": "3a42a16c-24a8-477d-b4fa-609c933b26c8", "type": "concept", "title": "Phosphagen, glycolytic, and oxidative systems"}, {"id": "f580cd79-93f3-4f1e-8537-bfc9fb170bc3", "type": "concept", "title": "Fuel selection and intensity"}, {"id": "53cc9947-5f25-4584-a19d-213a99341f78", "type": "concept", "title": "Lactate, oxygen uptake, and energy-system overlap"}]}, {"id": "3316a5c4-a4a2-4bd7-b224-cec5cb6a63bb", "type": "subtopic", "title": "Acute cardiorespiratory and muscular responses", "description": "The gist is to connect what students feel during exercise to measurable physiology.", "children": [{"id": "c323746c-5030-431f-abbd-8be95fe0d65c", "type": "concept", "title": "Heart rate, stroke volume, cardiac output, ventilation, and blood pressure"}, {"id": "acba2e85-d24c-4610-85e8-494ec904cd73", "type": "concept", "title": "Muscle recruitment, fatigue, and temperature"}, {"id": "4fd0f272-b779-4183-9a63-815445ccb9e8", "type": "concept", "title": "Hormonal and metabolic responses"}]}, {"id": "12110207-a28b-4034-8262-95758e172769", "type": "subtopic", "title": "Training adaptations", "description": "Learners preview how repeated exercise stress changes the body over time.", "children": [{"id": "01b1e5a6-847b-4202-81cb-8b96061e10ff", "type": "concept", "title": "Aerobic, resistance, interval, and flexibility training adaptations"}, {"id": "eb5d446a-cc0d-4520-931d-35be45bdf8a7", "type": "concept", "title": "Specificity, overload, reversibility, and individual variation"}, {"id": "7ed2f8fe-5603-4432-bde3-36370779ffb2", "type": "concept", "title": "Environmental stressors such as heat, cold, and altitude"}]}]}, {"id": "cc20dc90-4bac-44b8-ad83-ef84f4ff0d21", "type": "topic", "title": "Motor Behavior: Motor Learning, Motor Control, and Skill Acquisition", "description": "Study how the nervous system controls movement and how people learn motor skills.", "children": [{"id": "f6507dd8-db93-4796-842c-cbe1950f8b20", "type": "subtopic", "title": "Motor control foundations", "description": "Students learn how the nervous system coordinates posture, balance, and voluntary movement.", "children": [{"id": "c34520df-6b73-4277-bc60-79a896da3296", "type": "concept", "title": "Sensorimotor integration"}, {"id": "fe8ca1a7-258a-4c58-a988-ffcd476dbe91", "type": "concept", "title": "Reflexes, motor units, spinal cord, cortex, cerebellum, and basal ganglia"}, {"id": "582c9865-43a8-401b-9c48-a2b53b1fcd37", "type": "concept", "title": "Postural control and balance"}]}, {"id": "dc71cc09-ae6f-4676-8cd2-303d8e558ad7", "type": "subtopic", "title": "Motor learning principles", "description": "The point is to understand why practice design changes skill development.", "children": [{"id": "a40026c9-5a20-4b5d-a887-db0c33acc770", "type": "concept", "title": "Stages of learning"}, {"id": "814346c4-79ce-42df-b1ac-085f2da88b74", "type": "concept", "title": "Feedback, attention, memory, transfer, and retention"}, {"id": "f483c7e6-268e-44a9-91a6-d4cf5ae513db", "type": "concept", "title": "Blocked, random, variable, and deliberate practice"}]}, {"id": "786cedbd-c84a-41bb-a588-844e750df819", "type": "subtopic", "title": "Skill assessment and coaching implications", "description": "Learners connect theory to teaching, coaching, therapy, and performance environments.", "children": [{"id": "dc78e626-37d2-4eb9-8750-afede4bd6763", "type": "concept", "title": "Open and closed skills"}, {"id": "fa607434-a19b-4633-8f37-dfff02deba67", "type": "concept", "title": "Motor skill classification"}, {"id": "638830b9-c883-40a3-87fb-cf5f45b36cb6", "type": "concept", "title": "Error detection, cues, demonstrations, and constraints"}]}]}, {"id": "18d68679-4d44-4188-8fd7-5039de02d7a9", "type": "topic", "title": "Sport, Exercise Psychology, Motivation, and Behavior Change", "description": "Explore the mental, social, and behavioral forces that shape activity, performance, and adherence.", "children": [{"id": "30ea660c-1f40-48c0-bfb2-2ec3ab6c8d4a", "type": "subtopic", "title": "Psychological foundations of activity", "description": "Students learn that beliefs, emotions, identity, and social context strongly shape participation.", "children": [{"id": "f243dee0-13c6-4bb0-b8a6-56698b684788", "type": "concept", "title": "Motivation, self-efficacy, confidence, anxiety, and enjoyment"}, {"id": "f056b840-a3e7-4253-9dd9-4f3df2e88428", "type": "concept", "title": "Goal setting and feedback"}, {"id": "9ad3e739-0ae5-46ea-80f1-4aa3ef418620", "type": "concept", "title": "Self-determination and social-cognitive perspectives"}]}, {"id": "abc4b7c1-5769-4d09-804a-4e18382bd7a0", "type": "subtopic", "title": "Behavior-change methods", "description": "This subtopic introduces practical strategies for helping people start and maintain activity.", "children": [{"id": "6874d10f-036d-48e4-a448-b0da1e9b07de", "type": "concept", "title": "Readiness to change"}, {"id": "3d05c27b-2e9b-4116-bffb-31191bea386e", "type": "concept", "title": "Habit formation, planning, prompts, and self-monitoring"}, {"id": "128a8132-dae1-4ead-b6fc-dea9d8b0010c", "type": "concept", "title": "Motivational interviewing basics"}]}, {"id": "001b1f4b-7e4a-4e16-94fe-933880775585", "type": "subtopic", "title": "Performance and well-being", "description": "Learners examine mental skills without reducing athletes or exercisers to outcomes alone.", "children": [{"id": "23eef36a-198b-4169-9b51-aedf00aecd37", "type": "concept", "title": "Attention, arousal, imagery, routines, and resilience"}, {"id": "eab79819-d653-4d05-8fd9-966564d2f0fd", "type": "concept", "title": "Burnout, overtraining, identity, and mental health"}, {"id": "314d1181-12b0-4ef3-a546-a166ab69117a", "type": "concept", "title": "Team climate, coaching behavior, and belonging"}]}]}, {"id": "b74a9cae-54ab-4ed0-b8f3-0b5e49f786ce", "type": "topic", "title": "Nutrition, Energy Balance, Hydration, and Recovery in Movement Contexts", "description": "Understand how nutrition and recovery support health, training, and performance.", "children": [{"id": "2db34043-cdc4-4392-aa67-dcb580d4ab94", "type": "subtopic", "title": "Nutrition fundamentals", "description": "Students build enough nutrition literacy to understand training, recovery, and health claims critically.", "children": [{"id": "773c0f9b-70a4-4fdd-9dc5-2ee7191b682c", "type": "concept", "title": "Carbohydrate, fat, protein, vitamins, minerals, and fiber"}, {"id": "b636a809-fac0-4a2c-a7d8-9cfa6d99ed26", "type": "concept", "title": "Energy balance and body composition basics"}, {"id": "0c36cc28-5183-423f-9d95-7c571ffae707", "type": "concept", "title": "Nutrition needs across goals and populations"}]}, {"id": "5f32ea3d-b55e-4c4d-8f70-534aee8f71d9", "type": "subtopic", "title": "Hydration and fueling for activity", "description": "The gist is to match intake to exercise demands without drifting into rigid or unsafe advice.", "children": [{"id": "2434254d-40c4-42b8-919a-9c65da6ec2e8", "type": "concept", "title": "Fluid balance, electrolytes, heat stress, and sweat rate"}, {"id": "b3b5485e-c789-4c9d-af65-8a21d978322d", "type": "concept", "title": "Pre-, during-, and post-exercise fueling"}, {"id": "56614298-1a65-4d56-a0c1-e25cf73469dd", "type": "concept", "title": "Endurance, strength, team-sport, and recreational contexts"}]}, {"id": "1bc670cb-003e-48dc-a692-6a7e92db500b", "type": "subtopic", "title": "Recovery and risk", "description": "Learners understand recovery as part of adaptation, not an optional add-on.", "children": [{"id": "b5c95df1-c38f-45ef-8ec9-ff9e34bbf652", "type": "concept", "title": "Sleep, soreness, fatigue, and recovery monitoring"}, {"id": "898a4cac-5da7-4192-b2d3-979044eb2e0e", "type": "concept", "title": "Supplements and evidence quality"}, {"id": "1414feb5-720a-423c-bb33-860e5714891e", "type": "concept", "title": "Disordered eating risk, RED-S, and referral boundaries"}]}]}, {"id": "d4299436-0cae-4cdf-85af-a094b116548f", "type": "topic", "title": "Health and Fitness Assessment, Exercise Testing, and Risk Screening", "description": "Introduce safe, evidence-based assessment of readiness, fitness, function, and goals.", "children": [{"id": "59a0863e-a92b-424d-ad3e-389fe33ab802", "type": "subtopic", "title": "Preparticipation screening", "description": "Students learn how to make assessment safer and more ethical before testing begins.", "children": [{"id": "53a9bfb2-02df-4836-95b4-3159083e6ec4", "type": "concept", "title": "Health history, PAR-Q style tools, and risk factors"}, {"id": "039bebc1-3810-494f-845f-5b75c4ca5235", "type": "concept", "title": "Contraindications and referral triggers"}, {"id": "bda3dbcc-e2e8-41ab-80b5-ae7b5890d7e0", "type": "concept", "title": "Emergency planning and informed consent"}]}, {"id": "7867a238-9e31-4bbe-b5bb-3adaa7e32a63", "type": "subtopic", "title": "Fitness and function assessment", "description": "The point is to measure what matters while respecting validity, reliability, and context.", "children": [{"id": "2324d47b-d245-4043-bb4d-f68c72d2ba93", "type": "concept", "title": "Cardiorespiratory fitness, strength, muscular endurance, flexibility, balance, and mobility"}, {"id": "99acef40-4fee-442d-a45b-e48ff841df8b", "type": "concept", "title": "Body composition and limitations of common methods"}, {"id": "acd4c0e9-20e3-4080-8322-08b3d770eca9", "type": "concept", "title": "Functional movement screens and field tests"}]}, {"id": "7918f001-bfc2-49e7-910e-a84eef0add89", "type": "subtopic", "title": "Interpreting results", "description": "Learners translate test data into goals and next steps without overclaiming.", "children": [{"id": "8674a627-ea1b-4677-a2d7-ebe2120e3c97", "type": "concept", "title": "Norm-referenced and criterion-referenced interpretation"}, {"id": "ea704171-0af6-469d-b4a1-b210a60518ef", "type": "concept", "title": "Measurement error and retesting"}, {"id": "55186f44-25f9-4d77-8e56-f4c21253f434", "type": "concept", "title": "Client-centered goal setting and communication"}]}]}, {"id": "e856e9c9-cba7-4933-871e-dafd149df855", "type": "topic", "title": "Strength and Conditioning, Program Design, and Performance Monitoring", "description": "Learn the basic logic of training plans for strength, endurance, mobility, and power.", "children": [{"id": "7a7e2970-9256-46a8-aec1-c991ac0eda0d", "type": "subtopic", "title": "Training principles", "description": "Students learn the shared logic behind programs across health, fitness, and sport settings.", "children": [{"id": "2336482e-c993-4d9a-957c-43431fddd3e3", "type": "concept", "title": "Specificity, overload, progression, variation, recovery, and reversibility"}, {"id": "a54b7fb7-2ca3-47ba-bed2-0c061f4c9b19", "type": "concept", "title": "Frequency, intensity, time, type, volume, and density"}, {"id": "46f3fdb9-3b01-4aa0-b3fc-0e94c4ff0645", "type": "concept", "title": "Adaptation, fatigue, and readiness"}]}, {"id": "1f0e0790-5f3e-42d1-a083-5c4e5aa83e39", "type": "subtopic", "title": "Program design basics", "description": "The gist is to connect goals, assessments, constraints, and evidence into a coherent plan.", "children": [{"id": "0a7e9990-d040-4151-b07b-966892c2b267", "type": "concept", "title": "Resistance, aerobic, power, speed, agility, flexibility, and mobility training"}, {"id": "80d4edbe-1779-499b-91ce-ae98e81c2063", "type": "concept", "title": "Warm-ups, cool-downs, exercise selection, and technique"}, {"id": "4d20dd46-8df3-4491-9acc-ca31bbd37d1a", "type": "concept", "title": "Periodization and session structure"}]}, {"id": "7c1d4e55-3117-431d-a5f8-03066d333284", "type": "subtopic", "title": "Monitoring and adjustment", "description": "Learners practice using feedback to adapt training instead of blindly following a template.", "children": [{"id": "17044658-5518-4349-8df2-eec19a07236b", "type": "concept", "title": "Rating of perceived exertion, heart rate, load, velocity, wellness, and soreness"}, {"id": "7f689e14-b6a4-4f2c-bb66-841258eb76ac", "type": "concept", "title": "Progress tracking and plateaus"}, {"id": "b22358eb-53ff-4990-a304-5ad7206e0f8b", "type": "concept", "title": "Injury risk, recovery, and return-to-activity considerations"}]}]}, {"id": "691858ab-8235-4de3-940e-5081e0150b9f", "type": "topic", "title": "Adapted Physical Activity, Inclusive Practice, Aging, and Special Populations", "description": "Design movement opportunities that respect disability, age, health status, and lived context.", "children": [{"id": "4577cad6-b77b-42fa-9ee0-38264dfaff74", "type": "subtopic", "title": "Inclusive movement design", "description": "Students learn to design activity around people rather than forcing people into narrow programs.", "children": [{"id": "99dd4a5f-0ef3-4159-8ece-39602ded524a", "type": "concept", "title": "Universal design and reasonable accommodations"}, {"id": "1d34c051-393f-454d-b01b-624f62963925", "type": "concept", "title": "Communication, autonomy, dignity, and choice"}, {"id": "2f9922bc-dd11-436e-9e62-b6f4791ded04", "type": "concept", "title": "Equipment, environment, rules, and task modification"}]}, {"id": "f8e893bf-2423-4a55-a5f1-7957c92f8465", "type": "subtopic", "title": "Disability and adapted activity", "description": "The point is to build competence and humility when working with diverse bodies and needs.", "children": [{"id": "1ecdff27-1bc5-4e32-90bf-aef312126037", "type": "concept", "title": "Physical, sensory, intellectual, developmental, and chronic-health conditions"}, {"id": "233c97ea-192b-4015-b2e3-a9c9f18628a0", "type": "concept", "title": "Adapted sport and recreation"}, {"id": "1c202d97-a6e8-4ab3-947b-05783aec693c", "type": "concept", "title": "Legal and professional foundations such as ADA and IDEA concepts"}]}, {"id": "c5f1d715-59e7-4598-ace8-a13f9ec6f6a6", "type": "subtopic", "title": "Aging and clinical considerations", "description": "Learners see lifespan movement as prevention, function, independence, and quality of life.", "children": [{"id": "ffcb5fbe-fe39-4335-af09-8bacd947ffe4", "type": "concept", "title": "Frailty, sarcopenia, balance, falls, mobility, and cognition"}, {"id": "905dfe1d-7ad2-4cb9-8c88-65d027eca567", "type": "concept", "title": "Cardiometabolic, musculoskeletal, neurological, and respiratory conside